ri":"http://data.europa.eu/esco/skill/b779205e-377e-4fda-88b0-8f6a3b71e02d","category":"H3","reason":"Consiste na técnica estruturada de medição espacial para dimensionar e posicionar equipamento.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b77b7ac5-f25f-4baf-8e49-dcd4f31899f2","category":"H4","reason":"Envolve contribuir para programas e campanhas de saúde pública mediante avaliação de prioridades e ações estratégicas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b77e7d1c-cbab-4fa8-95b9-6fc804786d2b","category":"H4","reason":"Trata da afetação e controlo estruturado de recursos humanos por turnos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b78a32fd-e99b-4b65-a01e-4b43b3b90167","category":"H1","reason":"É conhecimento especializado sobre perturbações da comunicação, no âmbito da psicologia e saúde.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b78f324d-e16c-43f8-97d2-50d3a7cd1fb3","category":"H2","reason":"O objeto principal é a utilização de plataformas e ambientes digitais concretos de aprendizagem.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b79955b0-8ca8-4a9f-8134-41c06cdbc234","category":"H3","reason":"Consiste na aplicação estruturada de normas e procedimentos de conformidade regulamentar na aviação.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7a03115-41c9-4167-a0b6-7e40cf0fd607","category":"H4","reason":"Envolve supervisionar e organizar ensaios de produto para assegurar requisitos operacionais, de qualidade e segurança.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7a26b32-c457-49aa-9a78-25ade10090e3","category":"H3","reason":"Trata da execução de procedimentos técnicos de manutenção de turbinas eólicas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7b1d2aa-c489-41c2-9fe3-9b237c0a79c3","category":"H1","reason":"É uma disciplina científica especializada sobre a topografia do fundo subaquático.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7b381f5-7de2-4f91-9a8f-524041cb47d9","category":"H1","reason":"Refere-se ao domínio de engenharia dedicado à instrumentação, sensores e controlo de processos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7b6db52-5bdf-49e9-95b6-f17827755a86","category":"H3","reason":"Consiste num processo técnico-artístico de adaptação de uma representação às condições do local.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7bad395-519b-4736-b798-b055b5cda0b1","category":"H3","reason":"Envolve o planeamento técnico do corte de material para reduzir desperdício e assegurar margens de ajuste.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7c00b85-e5b5-4c97-8bef-f0d7bd9db8d7","category":"H3","reason":"Consiste na técnica de reproduzir desenhos ou designs em materiais específicos.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/b7c8f418-08d5-45d6-b697-ab26c6ecbfb4","category":"S1","reason":"O foco é a orientação relacional para compreender necessidades, aconselhar clientes e tratar reclamações.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7cd09b7-58d8-4f2e-87de-613ae629f270","category":"H1","reason":"É conhecimento científico especializado sobre a absorção, distribuição e transformação de medicamentos no organismo.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7cf2d84-6c43-4baa-98cf-816a27336701","category":"H3","reason":"Trata da execução de procedimentos técnicos de manutenção quotidiana de ferramentas e equipamento.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7d292ca-b873-407e-a1cf-0e7d1a2149cf","category":"H3","reason":"Consiste na aplicação de procedimentos clínicos de diagnóstico de perturbações urogenitais.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7dbaaab-ea76-4f23-b45c-69d715b52f43","category":"H3","reason":"Envolve a elaboração técnica e estruturada de termos e condições de acordos de licença.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7dce8db-f634-4a19-9ecd-83ed9a0ed15b","category":"H2","reason":"O objeto principal é a operação de sistemas e equipamentos concretos de bombagem e respetivos controlos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7e543e5-3f3e-4f01-8c45-8f872d09bf09","category":"H2","reason":"Refere-se à preparação e calibração de uma máquina de impressão offset, um equipamento concreto.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7e57889-a84f-440c-9e60-459aa69979e9","category":"H4","reason":"Envolve análise e previsão para orientar operações, eficiência e logística da cadeia de abastecimento.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/b7eabcd9-d1c5-4028-9dcc-57c536d5a2e8","category":"H1","reason":"Consiste em assistência técnica no domínio jurídico sucessório e na elaboração de testamentos.","certainty":"high"}]$m82_json$::jsonb;
  v_found integer;
begin
  select count(distinct item.uri) into v_found
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification');
  if v_found <> jsonb_array_length(v_input) then
    raise exception 'M82_ESCO_MAPPING_MISMATCH: found %, expected %', v_found, jsonb_array_length(v_input);
  end if;
  if exists (
    select mapping.concept_id
    from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
    join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
    join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
    group by mapping.concept_id having count(distinct item.category)>1
  ) then raise exception 'M82_ESCO_CANONICAL_CLASS_CONFLICT'; end if;
  insert into public.knowledge_competency_classifications
    (concept_id, subgroup_id, version, taxonomy_version, method, provenance)
  select distinct on (concept.id)
    concept.id, subgroup.id,
    coalesce((select max(history.version)+1 from public.knowledge_competency_classifications history
      where history.concept_id=concept.id),1),
    'competency-taxonomy-2.0.0', 'ai_assisted',
    jsonb_build_object('source','ESCO','sourceVersion','1.2.1','sourceURI',item.uri,
      'sourceHash','1b5e5356d4037cdd5c938131b385b9059a1e5f256ca621e8372b6633ec9aea80',
      'classifierVersion','prisma-competency-classification-1.1.0',
      'model','gpt-5.6-terra', 'reason',item.reason,'certainty',item.certainty,
      'agreement','M8.2-1.0.0')
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification')
  join public.competency_subgroups subgroup on subgroup.code=item.category and subgroup.scope='global' and subgroup.status='active'
  where not exists (select 1 from public.knowledge_competency_classifications current_class
    where current_class.concept_id=concept.id and current_class.is_current)
  order by concept.id,item.uri;
end $m82$;
